import { skillCategories } from '../../data/skills';
import { useIntersectionObserver } from '../../hooks/useIntersectionObserver';

export default function Skills() {
  const [observerRef, isVisible] = useIntersectionObserver();

  return (
    <section id="skills" className="py-24 px-6">
      <div className="max-w-5xl mx-auto rounded-lg border border-border bg-white/5 backdrop-blur-md overflow-hidden">
        <div className="p-6 md:p-8">
          <p className="section-label">Skills</p>
          <h2 className="text-3xl sm:text-4xl font-bold tracking-tight mb-12">
            What I work with
          </h2>

          <div
            ref={observerRef}
            className={`grid sm:grid-cols-2 gap-8 ${isVisible ? 'animate-fade-in' : 'opacity-0'}`}
          >
            {skillCategories.map((category) => (
              <div key={category.label}>
                <h3 className="text-sm text-fg-dim font-mono mb-3">
                  {category.label}
                </h3>
                <div className="flex flex-wrap gap-2">
                  {category.skills.map((skill) => (
                    <span
                      key={skill}
                      className="tech-badge"
                    >
                      {skill}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
